window.W = {
  studyChrome(title, badge, footRight) {
    return '<div class="study-header">' +
      '<div><div class="study-kicker">Exam App · Workspace Motion Study · Issue #10</div>' +
      '<h1 class="study-title">' + title + '</h1></div>' +
      '<div class="study-badge">' + badge + '</div>' +
      '</div>' +
      '<div class="study-footer">' +
      '<span>Provisional study · Nov 2026 · Pending owner identity &amp; High-Fidelity approval</span>' +
      '<span>' + footRight + '</span>' +
      '</div>';
  },
  logoLockupUrl(kit) {
    return 'data:image/svg+xml,' + encodeURIComponent(kit.module('logo-lockup.txt'));
  },
  logoMarkUrl(kit) {
    return 'data:image/svg+xml,' + encodeURIComponent(kit.module('logo-mark.txt'));
  },
  panelSvg() {
    return '<svg width="20" height="20" viewBox="0 0 20 20" fill="none">' +
      '<rect x="2" y="3" width="16" height="14" rx="2" stroke="currentColor" stroke-width="1.6"/>' +
      '<path d="M7 3V17" stroke="currentColor" stroke-width="1.6"/>' +
      '</svg>';
  },
  closeSvg() {
    return '<svg width="20" height="20" viewBox="0 0 20 20" fill="none">' +
      '<path d="M5 5L15 15M15 5L5 15" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>' +
      '</svg>';
  },
  docSvg() {
    return '<svg width="20" height="20" viewBox="0 0 20 20" fill="none">' +
      '<rect x="3" y="3" width="14" height="14" rx="2" stroke="currentColor" stroke-width="1.5"/>' +
      '<path d="M6 7H14M6 11H13" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>' +
      '</svg>';
  },
  checkSvg() {
    return '<svg width="16" height="16" viewBox="0 0 16 16" fill="none">' +
      '<path d="M3.5 8.5L6.5 11.5L12.5 5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>' +
      '</svg>';
  },
  crossSvg() {
    return '<svg width="16" height="16" viewBox="0 0 16 16" fill="none">' +
      '<path d="M4.5 4.5L11.5 11.5M11.5 4.5L4.5 11.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>' +
      '</svg>';
  }
};
